prts.feedbackvariables:
validInput: is(length(ans1)=3 and length(ans2)=3);
nonZeroDirection: not is(ans2=[0,0,0]);
goodPoint: if (ans1=p1 or ans1=p2) then true elseif validInput then collinear(p1,p2,ans1) else false;
stdDirUvect: if (validInput and nonZeroDirection) then myuvect(ans2) else [0,0,0];
goodDirection: is ((myuvect(p1-p2) = stdDirUvect) or (myuvect(p1-p2) = -stdDirUvect))
